import AVFoundation
import CoreAudio
import Foundation

/// Continuous health monitoring for the capture path, so a mic failure records
/// itself as it happens instead of being reconstructed afterwards.
///
/// Every previous round of "the mic is dead after sleep" was diagnosed from
/// whatever survived — and the app's own log only ever said `listening started`,
/// because that is all it knew. `listening` means `engine.start()` returned; it
/// has never meant that audio is arriving. So the app could hold a dead device
/// for hours and report itself healthy, which is exactly what it did.
///
/// This closes that gap with two cheap, continuous measurements:
///
/// - **Buffer liveness.** The tap reports every buffer here; a timer notices
///   when they stop while we believe we are capturing, and says so once
///   (`AUDIO STALL`), then says so again when they come back. That is the
///   difference between "listening" and "holding a dead device".
/// - **The device, from CoreAudio's own point of view.** Read straight from the
///   HAL, which is a property query — it does **not** open the device, so
///   sampling it costs nothing and cannot contribute to the rapid-cycling that
///   wedges a USB mic. `IsRunningSomewhere` is the one that matters: it is true
///   when *any* process has IO running on the device, so "no buffers arriving
///   while IsRunningSomewhere is true" says the stream is ours and it is dead,
///   rather than the device having simply gone away.
///
/// Logging is state-change-driven, not periodic: a line a minute for half an
/// hour buries everything else, so a routine heartbeat lands every ten minutes
/// and anything unusual (a stall starting or ending, the device set changing,
/// the format changing) is logged the moment it is seen.
final class AudioDiagnostics {

    // MARK: configuration

    /// How often the counters and the device are sampled. Cheap: a few HAL
    /// property reads and an integer swap.
    private let sampleInterval: TimeInterval = 5
    /// No buffers for this long, while we believe we are capturing, is a stall.
    /// Buffers arrive roughly every 0.17s (8192 frames at 48kHz), so this is
    /// two orders of magnitude of slack — it cannot fire on jitter.
    private let stallThreshold: TimeInterval = 15
    /// Buffers arriving at the full rate with *every* sample exactly zero for
    /// this long is a dead stream, not a quiet room: a real microphone always
    /// has a noise floor, and this window covers ~350 buffers (~180k
    /// stride-sampled points), so an exact 0.0 across all of them cannot be
    /// silence in front of a live capsule. Judged per five-second sample, so it
    /// is caught in a minute rather than on the ten-minute heartbeat — the
    /// failure it names needs the owner to go and unplug something. (#88)
    private let noSignalThreshold: TimeInterval = 60
    /// Routine "everything is fine" line, so the log shows the counter alive
    /// across a long quiet evening rather than going silent and looking dead.
    private let heartbeatInterval: TimeInterval = 600

    // MARK: tap-side counters
    //
    // Written on the audio thread, read on main. One lock, held for a handful of
    // instructions — the same shape VoiceCommand uses for the same reason.

    private let lock = NSLock()
    private var bufferCount = 0
    private var frameCount = 0
    private var peak: Float = 0
    /// Monotonic stamp of the last buffer. Deliberately `systemUptime`, which
    /// does **not** advance while the machine is asleep — the opposite of the
    /// choice in `AppDelegate.sleepStartedAt`, and for the opposite reason: this
    /// measures how long the stream has been silent *while we were awake*, so a
    /// sleep in the middle must not count as silence.
    private var lastBufferUptime: TimeInterval?

    // MARK: main-side state

    private var timer: Timer?
    /// Start of the current unbroken run of all-zero buffers (`systemUptime`),
    /// or nil if the last sample carried signal. Judged per sample rather than
    /// against `intervalPeak`, which spans the whole heartbeat and would smear
    /// one laugh across ten minutes of dead stream.
    private var zeroSince: TimeInterval?
    /// Start of the current unbroken run of "CoreAudio is offering an input
    /// device we could actually open" (`systemUptime`), nil if it is not.
    private var usableInputSince: TimeInterval?
    /// Whether we actually *saw* the current input device arrive, as opposed to
    /// finding it already there when sampling began. Only a witnessed arrival
    /// can be mid-enumeration from our point of view, so only a witnessed
    /// arrival has a settle time worth waiting out.
    private var witnessedArrival = false
    private var lastHeartbeat: TimeInterval = 0
    private var lastDevices: [InputDevice] = []
    private var activeFormat: AVAudioFormat?
    /// Cumulative across the process, for the heartbeat line — the per-sample
    /// counters are reset every tick.
    private var totalBuffers = 0
    private var totalFrames = 0
    /// Loudest sample seen since the last heartbeat. Spans the heartbeat
    /// interval so every number on that line describes the same window.
    private var intervalPeak: Float = 0

    /// What the capture path is *doing*, as distinct from what the app believes
    /// it is doing. `listening` only ever meant `engine.start()` returned, so it
    /// is true in all three of these states.
    enum Health: Equatable {
        /// Buffers arriving, carrying audio.
        case ok
        /// No buffers at all. The device went away, or the stream is dead.
        case stalled
        /// Buffers arriving at the full rate, every sample exactly zero: the
        /// device is enumerated and streaming, but not capturing. Measured once
        /// (#88) and it survived process exit *and* a coreaudiod restart — only
        /// physically re-plugging the microphone cleared it, so there is nothing
        /// this process can do about it beyond saying so.
        case noSignal
    }

    /// "The app believes it is capturing." Supplied by `AppDelegate`; without it
    /// a stall is meaningless, since no buffers is correct when paused.
    var isListening: (() -> Bool)?
    /// Fired on main whenever `health` changes. Lets the menu bar stop claiming
    /// to listen while the capture path is not actually delivering audio.
    var onHealthChanged: ((Health) -> Void)?

    /// What the capture path is currently believed to be doing. Main-thread only.
    private(set) var health: Health = .ok

    /// How long CoreAudio has *continuously* been offering an input device we
    /// could actually open, or nil if it is not offering one at all.
    ///
    /// This exists so nothing else has to build an `AVAudioEngine` to find out
    /// whether a microphone is there. Materializing `inputNode` opens the
    /// default input **and mints a hidden per-client aggregate device inside
    /// coreaudiod**, so asking that way costs a device open plus an aggregate
    /// create/destroy every time — which the retry ladder was doing once a
    /// minute, ~210 times over one 3h40m outage. This answer is already being
    /// computed every five seconds out of pure HAL property reads that never
    /// open anything, so the expensive way to ask was never buying information
    /// we didn't have. (#88)
    ///
    /// The *duration* rather than a bool because "it is there" and "it has
    /// finished arriving" are different claims: a USB mic is enumerating for a
    /// while after it first appears in the HAL, and opening one mid-enumeration
    /// is the other half of the same suspicion.
    ///
    /// A device that was **already present when we started watching** reports
    /// `.greatestFiniteMagnitude`, i.e. "settled, as far as anyone can tell".
    /// "It appeared N seconds ago" is a claim that can only be made about an
    /// arrival we witnessed; a mic that was there before this process existed
    /// has been there for however long the Mac has been up, and there is no
    /// enumeration race to lose. Measuring from first *observation* instead made
    /// every launch refuse for ~19s and look like the app hadn't started. (#100 follow-up)
    var usableInputFor: TimeInterval? {
        guard let since = usableInputSince else { return nil }
        guard witnessedArrival else { return .greatestFiniteMagnitude }
        return ProcessInfo.processInfo.systemUptime - since
    }

    // MARK: lifecycle

    /// Begin sampling. Main-thread only; safe to call twice.
    func start() {
        guard timer == nil else { return }
        lastHeartbeat = ProcessInfo.processInfo.systemUptime
        lastDevices = Self.inputDevices()
        // Seed the availability probe from this first look, because the timer
        // below does not fire until `sampleInterval` has elapsed — so without
        // this, `usableInputFor` is nil for the app's first five seconds and the
        // start path refuses on a microphone that is sitting right there. Not a
        // witnessed arrival: whatever is present now predates us. (#100 follow-up)
        if Self.hasUsableInput(lastDevices) {
            usableInputSince = ProcessInfo.processInfo.systemUptime
            witnessedArrival = false
        }
        let timer = Timer(timeInterval: sampleInterval, repeats: true) { [weak self] _ in
            self?.sample()
        }
        // .common so the sampling keeps running while a menu is open — the one
        // moment someone is actually looking at the status it reports.
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
        AppLog.shared.log("audio diagnostics started — \(Self.describe(lastDevices))")
    }

    func stop() {
        timer?.invalidate()
        timer = nil
    }

    /// Called from the audio tap, on the audio thread, for every buffer.
    func noteBuffer(_ buffer: AVAudioPCMBuffer) {
        let frames = Int(buffer.frameLength)
        // Stride-sampled peak: telling silence from audio does not need every
        // frame, and the audio thread should not pay for what it does not need.
        var localPeak: Float = 0
        if let channel = buffer.floatChannelData?[0] {
            var index = 0
            while index < frames {
                localPeak = max(localPeak, abs(channel[index]))
                index += 16
            }
        }
        let now = ProcessInfo.processInfo.systemUptime
        lock.lock()
        bufferCount += 1
        frameCount += frames
        peak = max(peak, localPeak)
        lastBufferUptime = now
        lock.unlock()
    }

    /// Capture started. Starts the stall clock from here, so the window before
    /// the first buffer is measured too — a start that never delivers anything
    /// is precisely the failure this exists to catch.
    func noteCaptureStarted(format: AVAudioFormat) {
        activeFormat = format
        lock.lock()
        lastBufferUptime = ProcessInfo.processInfo.systemUptime
        lock.unlock()
        resetHealth()
    }

    /// Capture stopped on purpose. Clears the stall clock so an intentional stop
    /// is never reported as a stall.
    func noteCaptureStopped(reason: String) {
        activeFormat = nil
        lock.lock()
        lastBufferUptime = nil
        lock.unlock()
        resetHealth()
    }

    // MARK: sampling

    private func sample() {
        let now = ProcessInfo.processInfo.systemUptime
        lock.lock()
        let buffers = bufferCount
        let frames = frameCount
        let localPeak = peak
        let last = lastBufferUptime
        bufferCount = 0
        frameCount = 0
        peak = 0
        lock.unlock()
        totalBuffers += buffers
        totalFrames += frames
        // Peak must span the whole heartbeat interval, not the last five-second
        // sample. Reported beside cumulative buffers/frames, a five-second peak
        // reads as if it covered the same span — so a laugh mid-interval could
        // be followed by a quiet moment and the line would report near-silence.
        intervalPeak = max(intervalPeak, localPeak)

        let silence = last.map { now - $0 }
        let listening = isListening?() ?? false

        // Device changes are logged whenever they are seen: the set changing
        // under a running engine is the event that precedes most failures here,
        // and CoreAudio's own notification is suppressed around our restarts.
        let devices = Self.inputDevices()
        if devices != lastDevices {
            // Two very different events wear the same diff, and conflating them
            // would bury the one that matters. A device appearing or vanishing
            // (or changing rate/channels/alive) is a hardware event worth a
            // WARN. `isRunningSomewhere` flipping is usually just us starting or
            // stopping capture — informative, but not an alarm. Observed
            // immediately in the field: the first restart after launch logged
            // "input devices changed" as a WARN when nothing had changed but our
            // own IO state.
            let changed = Self.identities(devices) != Self.identities(lastDevices)
            AppLog.shared.log(
                (changed ? "input devices changed — " : "input IO state changed — ")
                    + Self.describe(devices),
                level: changed ? "WARN" : "INFO")
            lastDevices = devices
        }

        // Track how long a genuinely openable input has been on offer, so the
        // start path can consult this instead of opening a device to find out.
        if Self.hasUsableInput(devices) {
            if usableInputSince == nil {
                // An arrival we watched happen — this one gets a settle window.
                usableInputSince = now
                witnessedArrival = true
            }
        } else {
            usableInputSince = nil
            witnessedArrival = false
        }

        // Extend or break the run of digital silence. Only judged when buffers
        // actually arrived: a sample with none says nothing about signal, and
        // treating it as either would make a stall look like a recovery.
        if listening, buffers > 0 {
            if localPeak > 0 {
                zeroSince = nil
            } else if zeroSince == nil {
                zeroSince = now
            }
        }

        // Stall outranks no-signal — with no buffers at all there is nothing to
        // judge the samples of, and "the stream stopped" is the more specific
        // claim. They are mutually exclusive in practice for the same reason.
        let next: Health
        if listening, let silence = silence, silence >= stallThreshold {
            next = .stalled
        } else if listening, let zeroSince = zeroSince,
                  now - zeroSince >= noSignalThreshold {
            next = .noSignal
        } else {
            next = .ok
        }
        setHealth(next, silence: silence, zeroFor: zeroSince.map { now - $0 },
                  devices: devices)

        if now - lastHeartbeat >= heartbeatInterval {
            lastHeartbeat = now
            var state = "not listening"
            if listening {
                switch health {
                case .ok:       state = "listening"
                case .stalled:  state = "listening-but-STALLED"
                case .noSignal: state = "listening-but-SILENT"
                }
            }
            AppLog.shared.log("audio health: \(state) "
                + "buffers=\(totalBuffers) frames=\(totalFrames) "
                + "peak=\(String(format: "%.4f", intervalPeak)) "
                + "\(healthSuffix(devices: devices))")
            intervalPeak = 0
        }
    }

    /// The one place a health transition is logged and published, so the log and
    /// the menu bar can never disagree about it. Logs on the *transition* only:
    /// the previous no-signal check was bolted to the heartbeat and repeated an
    /// identical ERROR every ten minutes for as long as the failure lasted,
    /// which is the line-a-minute noise this class is meant to avoid.
    private func setHealth(_ next: Health, silence: TimeInterval?,
                           zeroFor: TimeInterval?, devices: [InputDevice]) {
        guard next != health else { return }
        let previous = health
        health = next
        switch next {
        case .stalled:
            AppLog.shared.log("AUDIO STALL: no buffers for "
                + String(format: "%.0fs", silence ?? 0)
                + " while listening — \(healthSuffix(devices: devices))", level: "ERROR")
        case .noSignal:
            AppLog.shared.log("NO SIGNAL: buffers arriving at the normal rate for "
                + String(format: "%.0fs", zeroFor ?? 0)
                + " with every sample exactly zero — the microphone is enumerated but "
                + "not capturing. Unplugging it and reconnecting it is the only known "
                + "fix; quitting this app and restarting coreaudiod both leave it in "
                + "this state — \(healthSuffix(devices: devices))", level: "ERROR")
        case .ok:
            AppLog.shared.log(previous == .stalled
                ? "audio recovered — buffers are arriving again"
                : "audio recovered — the stream is carrying signal again")
        }
        onHealthChanged?(next)
    }

    /// Capture started or stopped on purpose: drop back to `.ok` without logging
    /// a recovery, because nothing recovered — we simply started or stopped.
    private func resetHealth() {
        zeroSince = nil
        guard health != .ok else { return }
        health = .ok
        onHealthChanged?(.ok)
    }

    private func healthSuffix(devices: [InputDevice]) -> String {
        var parts: [String] = []
        if let format = activeFormat {
            parts.append("tapFormat=\(Int(format.sampleRate))Hz/\(format.channelCount)ch")
        }
        parts.append(Self.describe(devices))
        return parts.joined(separator: " ")
    }

    /// One line describing what the app currently believes about the capture
    /// path. Logged at every sleep, wake and configuration change, so the log
    /// carries the before/after around each transition rather than only the
    /// transition itself.
    func snapshotLine() -> String {
        let now = ProcessInfo.processInfo.systemUptime
        lock.lock()
        let last = lastBufferUptime
        lock.unlock()
        let silence = last.map { String(format: "%.1fs ago", now - $0) } ?? "never"
        return "audio snapshot: lastBuffer=\(silence) totalBuffers=\(totalBuffers) "
            + healthSuffix(devices: Self.inputDevices())
    }

    // MARK: the CoreAudio HAL
    //
    // Property reads only. None of this opens the device or touches an
    // AVAudioEngine, which is what makes it safe to run every few seconds
    // forever: building an engine to find out whether a mic is there is how the
    // device gets cycled open and shut, and cycling is what wedges a USB mic.

    struct InputDevice: Equatable {
        var name: String
        var uid: String
        var transport: String
        var sampleRate: Double
        var channels: Int
        var isAlive: Bool
        var isRunningSomewhere: Bool
        var isDefault: Bool
    }

    private static func address(
        _ selector: AudioObjectPropertySelector,
        _ scope: AudioObjectPropertyScope = kAudioObjectPropertyScopeGlobal
    ) -> AudioObjectPropertyAddress {
        AudioObjectPropertyAddress(mSelector: selector, mScope: scope,
                                   mElement: kAudioObjectPropertyElementMain)
    }

    private static func uint32(_ object: AudioObjectID,
                               _ selector: AudioObjectPropertySelector) -> UInt32? {
        var addr = address(selector)
        var value: UInt32 = 0
        var size = UInt32(MemoryLayout<UInt32>.size)
        return AudioObjectGetPropertyData(object, &addr, 0, nil, &size, &value) == noErr
            ? value : nil
    }

    private static func float64(_ object: AudioObjectID,
                                _ selector: AudioObjectPropertySelector) -> Double? {
        var addr = address(selector)
        var value: Float64 = 0
        var size = UInt32(MemoryLayout<Float64>.size)
        return AudioObjectGetPropertyData(object, &addr, 0, nil, &size, &value) == noErr
            ? Double(value) : nil
    }

    private static func string(_ object: AudioObjectID,
                               _ selector: AudioObjectPropertySelector) -> String? {
        var addr = address(selector)
        var value: CFString = "" as CFString
        var size = UInt32(MemoryLayout<CFString>.size)
        let err = withUnsafeMutablePointer(to: &value) { pointer -> OSStatus in
            AudioObjectGetPropertyData(object, &addr, 0, nil, &size, pointer)
        }
        return err == noErr ? (value as String) : nil
    }

    /// Total input channels. Zero means "not an input device" — or an input
    /// device whose stream configuration has gone out from under it.
    private static func inputChannels(_ device: AudioDeviceID) -> Int {
        var addr = address(kAudioDevicePropertyStreamConfiguration,
                           kAudioDevicePropertyScopeInput)
        var size: UInt32 = 0
        guard AudioObjectGetPropertyDataSize(device, &addr, 0, nil, &size) == noErr,
              size > 0 else { return 0 }
        let raw = UnsafeMutableRawPointer.allocate(
            byteCount: Int(size), alignment: MemoryLayout<AudioBufferList>.alignment)
        defer { raw.deallocate() }
        guard AudioObjectGetPropertyData(device, &addr, 0, nil, &size, raw) == noErr else {
            return 0
        }
        let list = UnsafeMutableAudioBufferListPointer(
            raw.assumingMemoryBound(to: AudioBufferList.self))
        return list.reduce(0) { $0 + Int($1.mNumberChannels) }
    }

    private static func defaultInputDevice() -> AudioDeviceID {
        var addr = address(kAudioHardwarePropertyDefaultInputDevice)
        var device = AudioDeviceID(0)
        var size = UInt32(MemoryLayout<AudioDeviceID>.size)
        guard AudioObjectGetPropertyData(AudioObjectID(kAudioObjectSystemObject),
                                         &addr, 0, nil, &size, &device) == noErr else {
            return AudioDeviceID(kAudioObjectUnknown)
        }
        return device
    }

    private static func fourCC(_ value: UInt32) -> String {
        let bytes = [UInt8((value >> 24) & 0xFF), UInt8((value >> 16) & 0xFF),
                     UInt8((value >> 8) & 0xFF), UInt8(value & 0xFF)]
        return (String(bytes: bytes, encoding: .macOSRoman) ?? "????")
            .trimmingCharacters(in: .whitespaces)
    }

    /// Every device that exposes input channels, as CoreAudio sees it now.
    static func inputDevices() -> [InputDevice] {
        var addr = address(kAudioHardwarePropertyDevices)
        var size: UInt32 = 0
        let system = AudioObjectID(kAudioObjectSystemObject)
        guard AudioObjectGetPropertyDataSize(system, &addr, 0, nil, &size) == noErr,
              size > 0 else { return [] }
        var ids = [AudioDeviceID](repeating: 0,
                                  count: Int(size) / MemoryLayout<AudioDeviceID>.size)
        guard AudioObjectGetPropertyData(system, &addr, 0, nil, &size, &ids) == noErr else {
            return []
        }
        let defaultDevice = defaultInputDevice()
        return ids.compactMap { id in
            let channels = inputChannels(id)
            guard channels > 0 else { return nil }
            return InputDevice(
                name: string(id, kAudioObjectPropertyName) ?? "(unnamed)",
                uid: string(id, kAudioDevicePropertyDeviceUID) ?? "(no uid)",
                transport: uint32(id, kAudioDevicePropertyTransportType).map(fourCC) ?? "????",
                sampleRate: float64(id, kAudioDevicePropertyNominalSampleRate) ?? 0,
                channels: channels,
                isAlive: (uint32(id, kAudioDevicePropertyDeviceIsAlive) ?? 0) != 0,
                // True when *any* process has IO running on this device. No
                // buffers arriving while this is true means the running stream
                // is ours and it is dead — as opposed to the device being gone.
                isRunningSomewhere:
                    (uint32(id, kAudioDevicePropertyDeviceIsRunningSomewhere) ?? 0) != 0,
                isDefault: id == defaultDevice)
        }
    }

    /// Is any of these a device we could actually open and capture from?
    ///
    /// Three requirements, and the last two are the ones that bite:
    ///
    /// - **Not an aggregate.** `CADefaultDeviceAggregate-<pid>-<n>` is the
    ///   hidden per-client device coreaudiod mints for *us* when we open the
    ///   default input. Counting it would make the probe report a usable input
    ///   because we already opened one — true and useless.
    /// - **A sane format, not mere presence.** Mid-teardown an input lists as
    ///   `"(unnamed)"/????/0Hz/2ch/alive=y`: readable enough to enumerate and
    ///   impossible to capture from. A probe that accepts presence waves
    ///   through starts that cannot succeed — the same trap `outputFormat` set
    ///   one layer up. (#79)
    /// - **Alive**, which is the cheap part and the only one anyone remembers.
    private static func hasUsableInput(_ devices: [InputDevice]) -> Bool {
        let aggregate = fourCC(UInt32(kAudioDeviceTransportTypeAggregate))
        return devices.contains {
            $0.isAlive && $0.sampleRate > 0 && $0.channels > 0
                && $0.transport != aggregate
        }
    }

    /// Everything about the input device set *except* whether IO is running on
    /// it — i.e. the part that changing means the hardware changed under us,
    /// rather than us having started or stopped capturing.
    private static func identities(_ devices: [InputDevice]) -> [String] {
        devices.map {
            "\($0.uid)|\($0.name)|\($0.transport)|\($0.sampleRate)|\($0.channels)"
                + "|\($0.isAlive)|\($0.isDefault)"
        }
    }

    private static func describe(_ devices: [InputDevice]) -> String {
        guard !devices.isEmpty else { return "inputs=NONE" }
        let rendered = devices.map { device in
            "\(device.isDefault ? "*" : "")\"\(device.name)\"/\(device.transport)"
                + "/\(Int(device.sampleRate))Hz/\(device.channels)ch"
                + "/alive=\(device.isAlive ? "y" : "n")"
                + "/running=\(device.isRunningSomewhere ? "y" : "n")"
        }
        return "inputs=[\(rendered.joined(separator: " "))]"
    }
}

import AVFoundation
import ObjCExceptionTrap

/// Owns the microphone. A single input tap fans each captured buffer out to
/// every consumer (the laughter detector *and* the speech recogniser), so the
/// two never fight over the input node.
///
/// The `AVAudioEngine` is **rebuilt on every start** rather than held for the
/// process lifetime — see `prepareFormat()` for why that is load-bearing and not
/// tidiness. Because the engine instance changes, this class also owns the
/// `.AVAudioEngineConfigurationChange` observation and republishes it through
/// `onConfigurationChange`: an observer registered against a replaced engine goes
/// quiet, and a quiet config-change observer means the app stops noticing that
/// its microphone disappeared.
final class AudioHub {
    private var engine: AVAudioEngine
    private var configObserver: NSObjectProtocol?

    /// Called for every captured buffer, on the audio thread.
    var onBuffer: ((AVAudioPCMBuffer, AVAudioTime) -> Void)?

    /// Called on the main queue when CoreAudio reports that the current engine's
    /// configuration changed (device added, removed, or switched under us).
    var onConfigurationChange: (() -> Void)?

    /// The input format currently in use (valid only once `start(format:)` ran).
    private(set) var activeFormat: AVAudioFormat?

    var isRunning: Bool { engine.isRunning }

    init() {
        engine = Self.makeEngine()
        observeConfigurationChange()
    }

    /// Build an engine that is safe to `prepare()`.
    ///
    /// `AVAudioEngine` initializes its graph inside `prepare()` and asserts that
    /// at least one node is attached — `inputNode != nullptr || outputNode !=
    /// nullptr` — raising an uncatchable NSException when none is. A freshly
    /// constructed engine has none: `inputNode` is created lazily *on first
    /// access*, and touching the property is what attaches it. So materialize it
    /// here, as part of building an engine, rather than leaving it to a call
    /// order somewhere else.
    ///
    /// The pre-rebuild code survived only by accident: `requestListening()` calls
    /// `stop()`, which reaches `engine.inputNode.removeTap(onBus: 0)` and
    /// materialized the node on the single long-lived engine long before any
    /// `prepare()`. Rebuilding the engine after that call removed the accident,
    /// and every launch crashed one second in. (#72)
    private static func makeEngine() -> AVAudioEngine {
        let engine = AVAudioEngine()
        _ = engine.inputNode   // attaches it; do not "simplify" this away
        return engine
    }

    deinit {
        if let observer = configObserver {
            NotificationCenter.default.removeObserver(observer)
        }
    }

    /// Build a fresh engine and return its validated live input format, **without**
    /// starting capture. The input node's format is only reliable after prepare;
    /// returning it first lets the detector be configured to match *before* any
    /// audio flows (the analyzer must exist before buffers arrive, or the first
    /// buffers are dropped and analysis can fail to start).
    ///
    /// The engine is replaced here rather than reused, and that is the fix for
    /// #61. An `AVAudioEngine` caches the input hardware format when its input
    /// node is first materialized, and the cache does not follow the device: after
    /// CoreAudio tears the input down — a USB mic re-enumerating, or coreaudiod
    /// dropping its contexts when the display sleeps — `inputNode.outputFormat(
    /// forBus: 0)` keeps reporting the *old* rate. `installTap` validates against
    /// the freshly-queried hardware format instead, the two disagree, and it
    /// raises an uncatchable NSException. That killed the app on every single
    /// configuration change (six for six over fifteen days) — not the rare race
    /// the previous guard assumed, because comparing the stale cache against
    /// itself always passed. A new engine reads the hardware fresh, so the guard
    /// in `start(format:)` is meaningful again and the two formats agree.
    func prepareFormat() throws -> AVAudioFormat {
        renewEngine()
        // Trapped as well as installTap: #59 wrapped only the tap install, and
        // prepare() then raised from a path with no trap in it at all. Anything
        // that can raise on the way to capture gets the same treatment. (#72)
        try ObjCExceptionTrap.run { engine.prepare() }
        return try validatedFormat()
    }

    /// The tap format, checked against the *hardware* format that `installTap`
    /// asserts on.
    ///
    /// Read `inputFormat(forBus: 0)`, not `outputFormat`: `outputFormat` is the
    /// bus's output format, and with the input device torn down it still reports
    /// a plausible 48 kHz while `inputFormat` correctly reports 0. Checking
    /// `outputFormat` therefore could not detect an absent microphone at all — it
    /// waved through starts that could never succeed and left `installTap` to
    /// raise, which is what the exception trap kept catching once a minute while
    /// the displays slept. Requiring the two to agree means `installTap` is never
    /// reached in the mismatch state. (#76)
    private func validatedFormat() throws -> AVAudioFormat {
        let input = engine.inputNode
        let hardware = input.inputFormat(forBus: 0)
        let bus = input.outputFormat(forBus: 0)
        guard hardware.sampleRate > 0, hardware.channelCount > 0 else {
            throw NSError(domain: "LaughCounter", code: 1, userInfo: [
                NSLocalizedDescriptionKey:
                    "no input hardware — the microphone is not available "
                    + "(sampleRate=\(hardware.sampleRate), channels=\(hardware.channelCount))",
            ])
        }
        guard hardware.sampleRate == bus.sampleRate,
              hardware.channelCount == bus.channelCount else {
            throw NSError(domain: "LaughCounter", code: 2, userInfo: [
                NSLocalizedDescriptionKey:
                    "input format unsettled "
                    + "(hardware \(hardware.sampleRate)Hz/\(hardware.channelCount)ch, "
                    + "bus \(bus.sampleRate)Hz/\(bus.channelCount)ch)",
            ])
        }
        return bus
    }

    /// Install the tap and start capture, using a format from `prepareFormat()`.
    func start(format: AVAudioFormat) throws {
        let input = engine.inputNode
        // Re-validate against the hardware immediately before the tap: the device
        // can still vanish between prepareFormat() and here (dock unplug,
        // wake-time re-enumeration), and a mismatch reaching installTap is what
        // raises. Checking the same pair as prepareFormat did, because the bus
        // format alone cannot tell an absent device from a present one. (#76)
        let live = try validatedFormat()
        guard live.sampleRate == format.sampleRate,
              live.channelCount == format.channelCount else {
            throw NSError(domain: "LaughCounter", code: 3, userInfo: [
                NSLocalizedDescriptionKey:
                    "input device changed between prepare and start "
                    + "(expected \(format.sampleRate)Hz/\(format.channelCount)ch, "
                    + "live \(live.sampleRate)Hz/\(live.channelCount)ch)",
            ])
        }
        input.removeTap(onBus: 0)   // no-op if none installed; keeps restart clean
        // Backstop: installTap raises an *uncatchable* NSException if its format
        // disagrees with the live hardware, and Swift cannot catch one — it aborts
        // the process, skipping the tap teardown in applicationWillTerminate and
        // leaving the IOProc registered, which is exactly what wedges a USB webcam
        // mic until it is physically re-plugged. This is not theoretical and not
        // dead code: it demonstrably caught that exception once a minute while the
        // displays slept, which is the only reason the app survived. The guard
        // above should now keep us off that path; this stays because there is no
        // atomic API and being wrong here costs the microphone.
        try ObjCExceptionTrap.run {
            input.installTap(onBus: 0, bufferSize: 8192, format: format) { [weak self] buffer, when in
                self?.onBuffer?(buffer, when)
            }
        }
        try engine.start()
        activeFormat = format
    }

    func stop() {
        engine.inputNode.removeTap(onBus: 0)
        // Unconditional: engine.stop() is safe on a non-running engine, and it also
        // releases what engine.prepare() allocated — a prepare()-then-throw path
        // (prepareFormat/configure failing before start) would otherwise leave the
        // initialized input unit holding the device.
        engine.stop()
        activeFormat = nil
    }

    /// Tear the current engine down and put a fresh one in its place. Stopping
    /// first is what keeps the release-the-mic invariant: dropping the last
    /// reference to a *running* engine would abandon its tap and IOProc on the
    /// device instead of deregistering them.
    private func renewEngine() {
        stop()
        engine = Self.makeEngine()
        observeConfigurationChange()
    }

    /// (Re)point the configuration-change observation at the current engine.
    private func observeConfigurationChange() {
        if let observer = configObserver {
            NotificationCenter.default.removeObserver(observer)
        }
        // Delivered on the main queue so the callback can touch app state directly;
        // CoreAudio posts this from whatever thread noticed the change.
        configObserver = NotificationCenter.default.addObserver(
            forName: .AVAudioEngineConfigurationChange, object: engine, queue: .main
        ) { [weak self] _ in
            self?.onConfigurationChange?()
        }
    }
}

import AppKit
import AVFoundation
import Speech

final class AppDelegate: NSObject, NSApplicationDelegate {
    private var statusItem: NSStatusItem!
    private let store = LaughStore()
    private let counter = LaughCounter()
    private let audio = AudioHub()
    private let detector = LaughDetector()
    private let voice = VoiceCommand()
    // Runs for the whole process lifetime, not just while capturing: it samples
    // buffer liveness and the CoreAudio device list continuously so a mic
    // failure records itself as it happens. Every previous round of "the mic is
    // dead after sleep" had to be reconstructed from a log that only ever said
    // "listening started".
    private let diagnostics = AudioDiagnostics()
    private var micGranted = false
    private var listening = false
    // (Re)starting the engine itself posts .AVAudioEngineConfigurationChange, so
    // we suppress that notification around our own (re)starts to avoid a restart
    // loop that would keep the engine from ever running long enough to detect.
    private var suppressConfigChange = false
    // Single-flight + rate-limit for (re)starts: repeatedly stop/starting a USB
    // mic in quick succession can wedge it, so restarts can never overlap or
    // rapid-cycle — an extra request while one is in flight is coalesced to one.
    private var restartInFlight = false
    private var restartQueued = false
    // Every intentional stop (sleep, terminate) and every accepted restart bumps
    // this; the delayed finishListening/settle closures capture it when scheduled
    // and abort if it moved. Without it, a stop can't cancel the +0.4s restart it
    // raced with — sleep during that gap would start the engine going *into*
    // sleep (carrying a live IOProc into sleep, the wedge condition), or fire it
    // at wake before the hardware settles. asyncAfter timers scheduled before
    // sleep fire immediately ON wake, which makes this race very reachable.
    private var restartGeneration = 0
    // A config-change notification arrived while suppressConfigChange was up.
    // The suppression must swallow our own stop/start echoes (reacting to them
    // would loop), but it can also swallow a *genuine* device event — noted here
    // so the settle closure can reconcile by state instead of losing the event.
    private var configChangeSwallowed = false
    // True from willSleep until the post-wake settle delay ends. Gates both
    // requestListening and the config-change handler: CoreAudio tears down /
    // switches devices while the machine heads into sleep, and reacting to those
    // notifications would restart capture into sleep right after the intentional
    // willSleep teardown.
    private var sleeping = false
    // Speech may only auto-(re)start once authorization was actually granted.
    private var speechAuthorized = false

    // Why the counter is *not* meant to be running — nil means it is. Held as one
    // field rather than a bool plus a separate reason so the menu, the tooltip and
    // the wake path always agree on both whether the counter is off and why.
    private var offReason: String? = "starting up"
    /// "The counter is meant to be running", as opposed to `listening` ("the engine
    /// actually is"). Sleep/standby suspends capture without touching this, so the
    /// return path knows the counter was active and switches it back on; a start
    /// that merely *failed* keeps the intent too, so the retry ladder below still
    /// applies. It is false only when we are not meant to be listening (paused,
    /// microphone denied, before the first start) — and then a return from standby
    /// deliberately resumes nothing.
    private var listeningIntent: Bool { offReason == nil }
    // Consecutive failed starts. Drives the post-standby retry ladder: a mic
    // that was powered down for a long standby can take several seconds longer
    // to re-enumerate than the wake settle delay allows, and a failed start
    // emits no further event to recover on. Reset on every successful start,
    // on a system return, and on a manual resume.
    private var startFailureStreak = 0
    // Identifies the one in-flight resume. Returning from standby fires a *burst*
    // of signals (wake, displays, session, unlock) that must schedule a single
    // resume between them; a stale timer compares its id and does nothing.
    private var resumeID = 0
    private var pendingResumeID: Int?
    // Wall-clock (not systemUptime, which does not advance while asleep) stamp of
    // the last willSleep, so the return path can tell a brief sleep from a long
    // standby and give the hardware proportionally longer to come back.
    private var sleepStartedAt: Date?

    /// Settle delay after an ordinary short sleep.
    private let wakeSettleDelay = 1.0
    /// Settle delay after a long sleep/standby, where the machine has powered the
    /// USB bus down and devices re-enumerate well after the wake notification.
    private let standbySettleDelay = 2.5
    /// A sleep at least this long is treated as standby for settling purposes.
    private let standbyThreshold = 300.0
    /// How long an input device must have been continuously present in the HAL
    /// before we will open it. Longer than `AudioDiagnostics`' 5s sample
    /// interval, so it always spans at least one full sample and can never be
    /// satisfied by the same observation that first revealed the device — which
    /// is exactly what happened when the mic came back wedged. (#88)
    private let deviceSettleDelay = 6.0
    /// How many fast doubling attempts before dropping to `maxBackoffDelay`.
    private let maxStartRetries = 5
    /// Ceiling for the retry backoff, and the steady interval after it.
    private let maxBackoffDelay = 60.0

    // Opt-in "keep the Mac awake so it keeps hearing laughs during a long movie".
    // Off by default; the choice persists across launches. While enabled *and*
    // listening we hold a power assertion that blocks idle *system* sleep (the
    // display can still sleep — we only need audio to keep running). It does not
    // block lid-close or a manual Sleep, and it costs battery, so it's opt-in.
    private let keepAwakeDefaultsKey = "keepMacAwakeWhileListening"
    private var keepAwake = false
    private var sleepAssertion: NSObjectProtocol?

    func applicationDidFinishLaunching(_ notification: Notification) {
        statusItem = NSStatusBar.system.statusItem(withLength: NSStatusItem.variableLength)
        keepAwake = UserDefaults.standard.bool(forKey: keepAwakeDefaultsKey)  // false if unset
        refreshTitle()
        buildMenu()
        wireUp()
        observeSystemEvents()
        AppLog.shared.log("app launched")
        // Before requesting the mic, so the log records what CoreAudio saw at
        // launch even if permission is denied or the first start fails.
        diagnostics.start()
        requestPermissionsAndStart()
    }

    // MARK: wiring

    private func wireUp() {
        // A counted laugh → log it with the you-vs-TV hypothesis, and blip only for
        // *your* laughs (blipping at every TV laugh would be maddening).
        counter.onLaugh = { [weak self] event in
            guard let self = self else { return }
            self.store.append(event)
            AppLog.shared.log(String(format: "laugh logged origin=%@ peak=%.2f dur=%.2f — %@",
                                     event.origin, event.peak, event.duration, event.originReason))
            if event.origin == "me" { Chime.play(times: 1) }
            DispatchQueue.main.async { self.refreshTitle() }
        }
        // Sub-threshold episode → log it as a candidate (silent, uncounted) so later
        // "I laughed" feedback has a nearby event to align to.
        counter.onCandidate = { [weak self] event in
            self?.store.append(event, label: "candidate")
            AppLog.shared.log(String(format: "candidate logged origin=%@ peak=%.2f dur=%.2f — %@",
                                     event.origin, event.peak, event.duration, event.originReason))
        }
        // Each analysis window → feed the counter (real audio timing inside).
        detector.onObservation = { [weak self] obs in
            self?.counter.update(obs)
        }
        // "I just laughed": spoken command vs the menu/keyboard get different sources.
        voice.onTrigger = { [weak self] in self?.markMissed(source: "voice") }
        // One mic tap, fanned out to both consumers. Diagnostics first, so a
        // buffer is recorded as having arrived even if a consumer below throws
        // or hangs — "did audio reach us" must not depend on what we do with it.
        audio.onBuffer = { [weak self] buffer, when in
            self?.diagnostics.noteBuffer(buffer)
            self?.detector.analyze(buffer, at: when)
            self?.voice.append(buffer)
        }
        // No buffers is the correct state when paused or stopped, so the stall
        // detector needs to know what we believe we are doing.
        diagnostics.isListening = { [weak self] in self?.listening ?? false }
        // The menu must stop claiming to listen the moment the capture path
        // stops delivering audio — that false "listening" is what hid this
        // failure for entire evenings, and then hid it again in its no-signal
        // shape while the diagnostics were logging the truth at ERROR. (#88)
        diagnostics.onHealthChanged = { [weak self] _ in
            guard let self = self else { return }
            self.refreshTitle()
            self.buildMenu()
        }
    }

    private func markMissed(source: String) {
        store.appendMissed(source: source)
        AppLog.shared.log("missed laugh logged via \(source)")
        Chime.play(times: 2)
        DispatchQueue.main.async { self.refreshTitle() }
    }

    // MARK: permissions + start

    private func requestPermissionsAndStart() {
        AVCaptureDevice.requestAccess(for: .audio) { [weak self] granted in
            DispatchQueue.main.async {
                guard let self = self else { return }
                self.micGranted = granted
                if granted {
                    self.requestListening()
                    self.requestSpeech()
                } else {
                    self.offReason = "no microphone access"
                    AppLog.shared.log("microphone access denied", level: "ERROR")
                    self.showMicDenied()
                }
            }
        }
    }

    /// Single-flight, rate-limited entry to (re)start listening. Every trigger
    /// (launch, wake, config-change, manual resume) goes through here so the audio
    /// engine can never overlap-restart or rapid-cycle — which can wedge a USB mic.
    /// Tears down, lets the input device settle briefly, then re-acquires.
    private func requestListening() {
        guard micGranted else { return }
        // Record the intent before the sleep gate, so a manual "Start listening"
        // clicked during a sleep transition is still honored by the resume — and
        // so it clears a pause, which is what asking to listen means.
        offReason = nil
        if sleeping {                  // heading into (or settling out of) sleep:
            // the post-wake resume is the one path out; log so a swallowed manual
            // click is visible in the activity log rather than silently ignored
            AppLog.shared.log("listening request ignored (sleep transition in progress)")
            return
        }
        if restartInFlight {           // coalesce; don't stack restarts
            restartQueued = true
            return
        }
        restartInFlight = true
        suppressConfigChange = true    // ignore the config-changes our stop/start emits
        configChangeSwallowed = false  // fresh window; note only events from this cycle
        restartGeneration &+= 1
        let generation = restartGeneration
        counter.flush()
        counter.reset()
        detector.reset()
        audio.stop()
        listening = false
        refreshTitle()
        // Let the (USB) input device release before re-acquiring — reacquiring
        // immediately after teardown is what can wedge some USB mics.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) { [weak self] in
            self?.finishListening(generation: generation)
        }
    }

    private func finishListening(generation: Int) {
        // A stop (sleep/terminate) superseded this restart while it waited — the
        // mic must stay released, not be re-acquired behind the stop's back.
        guard generation == restartGeneration else { return }
        do {
            // Ask the HAL whether there is anything worth opening BEFORE
            // building an engine to find out. Both callers land here — the
            // retry ladder and the config-change handler — so this is the one
            // chokepoint in front of the only expensive question in the app.
            try requireSettledInputDevice()
            // Configure the analyzer BEFORE audio flows, so no early buffers are
            // dropped and analysis reliably starts (matches the original order).
            let format = try audio.prepareFormat()
            try detector.configure(format: format)
            try audio.start(format: format)
            listening = true
            startFailureStreak = 0
            // Starts the stall clock from here, so the gap before the *first*
            // buffer counts: a start that returns cleanly and then delivers
            // nothing is the exact failure this is here to catch.
            diagnostics.noteCaptureStarted(format: format)
            AppLog.shared.log("listening started "
                + "(sampleRate=\(Int(format.sampleRate)), channels=\(format.channelCount))")
        } catch {
            audio.stop()
            listening = false
            startFailureStreak += 1
            diagnostics.noteCaptureStopped(reason: "start failed")
            AppLog.shared.log("could not start listening: \(error.localizedDescription)"
                + " — \(diagnostics.snapshotLine())", level: "ERROR")
        }
        refreshTitle()
        buildMenu()
        // Settle window: no further restart (or config-change reaction) until the
        // engine has run undisturbed for a moment. Then honor any coalesced request.
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.2) { [weak self] in
            guard let self = self, generation == self.restartGeneration else { return }
            self.suppressConfigChange = false
            self.restartInFlight = false
            let swallowed = self.configChangeSwallowed
            self.configChangeSwallowed = false
            if self.restartQueued {
                self.restartQueued = false
                self.requestListening()
            } else if self.listening && !self.audio.isRunning {
                // A genuine config change landed inside the suppress window and
                // halted the engine (AVAudioEngine stops rendering when the
                // device changes under it). The suppression rightly ignored the
                // notification — self-emitted ones would loop — so reconcile by
                // state instead: "listening" but engine dead means we owe a
                // restart, otherwise the UI claims listening while nothing flows.
                AppLog.shared.log("engine halted during settle — restarting", level: "WARN")
                self.requestListening()
            } else if !self.listening && swallowed {
                // Complementary case: this cycle's start FAILED (no device yet),
                // and the device's arrival notification landed inside the window.
                // Dropping it would leave the app "not listening" with no further
                // event to recover on. One retry per swallowed event — a dead mic
                // emits no events, so this can't poll forever.
                AppLog.shared.log("device event during settle after failed start — retrying")
                self.requestListening()
            } else if !self.listening && self.listeningIntent {
                // The counter is meant to be on but the start failed and no device
                // event arrived to hang a retry off. The reachable case is a return
                // from standby: the machine powered the USB bus down, so the mic is
                // still re-enumerating when the settle window ends and there is
                // nothing left to recover on — the app would sit silently "not
                // listening" until someone opened the menu. So back off and try
                // again, doubling each time (2s, 4s … 32s) and giving up after
                // `maxStartRetries`: bounded, because a mic that is gone for good
                // emits nothing and must not be polled forever, and slow, because
                // rapid-cycling a USB mic is what wedges it in the first place.
                self.scheduleStartRetry(generation: generation)
            }
        }
    }

    /// Refuse to open the microphone unless CoreAudio is offering one worth
    /// opening, and it has been on offer long enough to have finished arriving.
    /// Throws into `finishListening`'s existing catch, so a refusal reuses the
    /// whole failed-start path — logged, counted, retried — rather than needing
    /// a second recovery mechanism beside it.
    ///
    /// This is the fix for the thing that made this app abnormal (#88). Building
    /// an `AVAudioEngine` to ask "is there a mic?" is not a format read: the
    /// engine materializes `inputNode`, which opens the default input device and
    /// mints a hidden per-client aggregate device inside coreaudiod, and every
    /// failed attempt tears that back down. One measured outage ran that cycle
    /// ~210 times over 3h40m — a rate of device open/close no ordinary audio app
    /// comes close to, against hardware that was not there to begin with. The
    /// diagnostics timer answers the same question every five seconds with HAL
    /// property reads that open nothing, so the ladder was paying that price for
    /// information it already had.
    ///
    /// The settle requirement is the second half. The wedge episode opened the
    /// device *in the same second it appeared* in the HAL (a config-change
    /// notification arriving mid-enumeration, not the ladder), and a USB audio
    /// device is still bringing its streaming interface up for a while after it
    /// first becomes enumerable. Requiring it to have been continuously present
    /// across at least one full diagnostics sample means we never do that again.
    /// **Unproven as the cause** — the device reported a sane 48kHz/2ch when we
    /// grabbed it — but it costs one retry interval and removes the one action
    /// we take that could plausibly damage a device mid-enumeration.
    private func requireSettledInputDevice() throws {
        guard let present = diagnostics.usableInputFor else {
            throw NSError(domain: "LaughCounter", code: 10, userInfo: [
                NSLocalizedDescriptionKey:
                    "no input hardware — CoreAudio is offering no input device "
                    + "that could be opened",
            ])
        }
        guard present >= deviceSettleDelay else {
            throw NSError(domain: "LaughCounter", code: 11, userInfo: [
                NSLocalizedDescriptionKey: String(
                    format: "input device appeared %.0fs ago — letting it finish "
                        + "enumerating before opening it", present),
            ])
        }
    }

    /// Back-off retry after a failed start, generation-guarded like every other
    /// deferred restart: an intentional stop, or any restart accepted meanwhile,
    /// moves the generation and this retry aborts rather than re-acquiring the mic
    /// behind it. Main-thread only.
    private func scheduleStartRetry(generation: Int) {
        let attempt = startFailureStreak
        // Double up to the ceiling, then keep checking at that interval for as
        // long as the counter is meant to be on. Deliberately never gives up: the
        // measured cause of a long outage is the input device being torn down
        // while the displays sleep, which lasted 28 minutes in one observation —
        // no bounded ladder covers that, and the old five attempts (~62s) expired
        // with the cause still fully present, telling the user to reconnect a
        // microphone that was fine. (#76)
        //
        // This comment used to claim an attempt was "a cheap format read". It was
        // not — `prepareFormat()` built an engine, opened the default input and
        // churned a hidden aggregate device, ~210 times over one outage. It *is*
        // one now, because `requireSettledInputDevice()` refuses on a free HAL
        // read before any of that happens, so a check against absent hardware
        // costs nothing and touches nothing. (#88)
        let delay = min(Double(1 << min(attempt, 6)), maxBackoffDelay)
        if attempt <= maxStartRetries {
            AppLog.shared.log("start failed — retrying in \(Int(delay))s "
                + "(attempt \(attempt) of \(maxStartRetries))", level: "WARN")
        } else if attempt == maxStartRetries + 1 {
            // Announce the switch to slow checking once, then stay quiet until it
            // works — a line a minute for half an hour buries everything else.
            AppLog.shared.log("input device still unavailable — checking every "
                + "\(Int(maxBackoffDelay))s until it returns (expected while the "
                + "displays are asleep; no action needed)", level: "WARN")
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            guard let self = self, generation == self.restartGeneration else { return }
            guard self.listeningIntent, !self.listening else { return }
            self.requestListening()
        }
    }

    private func stopListening(reason: String) {
        // Invalidate the whole in-flight restart machinery, not just the queue
        // flag: a pending finishListening must never fire after an intentional
        // stop (it would re-acquire the mic right as the system sleeps), and the
        // in-flight/suppress latches must not stay stuck blocking future starts.
        restartGeneration &+= 1
        restartInFlight = false
        restartQueued = false
        suppressConfigChange = false
        pendingResumeID = nil   // a resume scheduled before this stop is void
        counter.flush()
        voice.stop()     // symmetric with resume; recognition restarts on wake
        audio.stop()
        listening = false
        diagnostics.noteCaptureStopped(reason: reason)
        AppLog.shared.log("listening stopped (\(reason))")
        refreshTitle()
        buildMenu()
    }

    private func requestSpeech() {
        SFSpeechRecognizer.requestAuthorization { [weak self] status in
            DispatchQueue.main.async {
                guard status == .authorized else {
                    AppLog.shared.log("speech recognition not authorized", level: "WARN")
                    return
                }
                self?.speechAuthorized = true
                self?.voice.start()
                self?.buildMenu()
            }
        }
    }

    // MARK: system power / audio events

    private func observeSystemEvents() {
        let ws = NSWorkspace.shared.notificationCenter
        ws.addObserver(self, selector: #selector(willSleep),
                       name: NSWorkspace.willSleepNotification, object: nil)
        // macOS has no "returned from standby" notification — standby is just a
        // deeper sleep, and the only guaranteed signal is the ordinary wake. But a
        // wake is not always a *return*: a dark/Power-Nap wake fires it with nobody
        // there and the machine drops straight back to sleep, and after a long
        // standby the mic can still be re-enumerating when our settle window ends.
        // So take the wake plus every other "the machine is back" signal and funnel
        // them into one coalesced resume; whichever lands first schedules it, the
        // later ones act as backstops if that resume didn't get the counter running.
        ws.addObserver(self, selector: #selector(didWake),
                       name: NSWorkspace.didWakeNotification, object: nil)
        ws.addObserver(self, selector: #selector(screensDidWake),
                       name: NSWorkspace.screensDidWakeNotification, object: nil)
        ws.addObserver(self, selector: #selector(sessionDidBecomeActive),
                       name: NSWorkspace.sessionDidBecomeActiveNotification, object: nil)
        // Unlocking after standby is the strongest "a person is actually back"
        // signal, but it only exists as a *distributed* notification. That is fine
        // for this app (non–App Store, no App Sandbox); under the sandbox it would
        // simply never arrive, and the workspace triggers above still cover us.
        DistributedNotificationCenter.default().addObserver(
            self, selector: #selector(screenDidUnlock),
            name: NSNotification.Name("com.apple.screenIsUnlocked"), object: nil)
        // AudioHub owns the .AVAudioEngineConfigurationChange observation because
        // it replaces the engine on every start (#61) and an observer bound to a
        // superseded instance would silently stop firing. It delivers on main.
        audio.onConfigurationChange = { [weak self] in self?.audioConfigChanged() }
    }

    @objc private func willSleep() {
        // Gate BEFORE tearing down: CoreAudio switches/removes devices while the
        // machine heads into sleep, and the resulting config-change notifications
        // must not restart capture behind this intentional stop.
        sleeping = true
        sleepStartedAt = Date()
        // What the capture path looked like going *in*, so the log carries both
        // sides of the transition rather than only the transition itself.
        AppLog.shared.log("entering sleep — \(diagnostics.snapshotLine())")
        // stopListening deliberately leaves `listeningIntent` alone: this is a
        // suspend, not "the counter was switched off", and the return path reads
        // that intent to decide whether to switch it back on.
        stopListening(reason: "system sleep")
    }

    @objc private func didWake() { systemDidReturn(reason: "system woke") }
    @objc private func screensDidWake() { systemDidReturn(reason: "displays woke") }
    @objc private func sessionDidBecomeActive() { systemDidReturn(reason: "session became active") }
    @objc private func screenDidUnlock() {
        // Distributed notifications are delivered on the main thread for an app
        // with a run loop, but say so explicitly rather than rely on it.
        DispatchQueue.main.async { [weak self] in self?.systemDidReturn(reason: "screen unlocked") }
    }

    /// One entry point for every "the machine is back" signal (wake from sleep or
    /// standby, displays waking, the session returning, the screen unlocking).
    /// Reactivates the counter **only if it was active before** — a Mac that was
    /// not listening when it went down comes back not listening.
    private func systemDidReturn(reason: String) {
        // These signals also fire with no sleep involved at all: the display
        // waking from the screensaver, a user switching back. Only a machine that
        // actually owes a resume reacts — restarting capture on every display wake
        // would rapid-cycle the mic (the wedge condition) for nothing.
        guard sleeping || (listeningIntent && !listening) else { return }
        if pendingResumeID != nil { return }   // the burst is one return, one resume
        // How long we were down, measured from willSleep. Nil means we never slept:
        // the signal is then a backstop over a start that failed earlier, and it
        // buys exactly one more attempt — not a fresh retry ladder.
        let asleep = sleepStartedAt.map { Date().timeIntervalSince($0) }
        // After a long standby the USB bus was powered down and devices come back
        // well after the wake notification, so settle for longer before re-acquiring.
        let standby = (asleep ?? 0) >= standbyThreshold
        let settle = standby ? standbySettleDelay : wakeSettleDelay
        let what = listeningIntent ? "resuming listening shortly"
                                   : "counter is \(offReason ?? "off"), staying off"
        if let asleep = asleep {
            AppLog.shared.log(String(format: "%@ after %.0fs %@ — %@", reason, asleep,
                                     standby ? "standby" : "sleep", what))
        } else {
            AppLog.shared.log("\(reason) while listening was down — \(what)")
        }
        resumeID &+= 1
        let id = resumeID
        pendingResumeID = id
        // Stay gated (`sleeping`) through the settle delay so wake-time device
        // re-enumeration can't trigger an early, un-settled restart; this resume is
        // the one entry point out of sleep. Capture the generation so a quick
        // re-sleep (lid closed again during the delay) aborts it — willSleep bumps
        // the generation, and this timer would otherwise fire immediately on the
        // *next* wake, un-gating and restarting un-settled.
        let generation = restartGeneration
        DispatchQueue.main.asyncAfter(deadline: .now() + settle) { [weak self] in
            guard let self = self, self.pendingResumeID == id else { return }
            self.pendingResumeID = nil
            guard generation == self.restartGeneration else {
                AppLog.shared.log("wake resume superseded by a later stop — skipping")
                return
            }
            self.sleeping = false          // always ungate, even when staying off,
            self.sleepStartedAt = nil      // or a manual start would stay blocked
            guard self.listeningIntent else {
                AppLog.shared.log("listening not resumed — counter is "
                    + "\(self.offReason ?? "off") (it was not active before sleep)")
                return
            }
            // The other side of the sleep transition: what CoreAudio is offering
            // at the moment we decide to re-acquire, which is the state that
            // decides whether the start about to run can possibly succeed.
            AppLog.shared.log("settled after \(reason) — \(self.diagnostics.snapshotLine())")
            // A real return from sleep earns a fresh retry ladder; a backstop
            // signal (no sleep behind it) gets the single attempt below instead.
            if asleep != nil { self.startFailureStreak = 0 }
            self.requestListening()
            if self.speechAuthorized { self.voice.start() }   // idempotent
        }
    }

    /// Main-queue only — `AudioHub` delivers the notification there.
    private func audioConfigChanged() {
        guard !sleeping else { return }
        if suppressConfigChange {
            configChangeSwallowed = true   // reconciled at settle time
            return
        }
        AppLog.shared.log("audio configuration changed — reconfiguring "
            + "(\(diagnostics.snapshotLine()))")
        requestListening()   // single-flighted + rate-limited inside
    }

    // MARK: menu bar

    /// `v0.3.1 (5)` — shown in the menu header so the running build is
    /// identifiable without a terminal.
    ///
    /// Read from `Bundle.main`, never a constant in the source: `Info.plist` is
    /// the one place the version lives, and the release workflow derives the tag
    /// from it, so a second copy here could disagree with the DMG it shipped in.
    /// The **build number matters as much as the version**: a merge that doesn't
    /// change `CFBundleShortVersionString` refreshes the same Release, so several
    /// distinct builds shipped as `0.2.1` and telling them apart meant reading
    /// symbol names out of a crash report. `CFBundleVersion` is what separates
    /// them. (#74)
    private static var versionLabel: String {
        let info = Bundle.main.infoDictionary
        let short = info?["CFBundleShortVersionString"] as? String
        let build = info?["CFBundleVersion"] as? String
        switch (short, build) {
        case let (version?, build?): return "v\(version) (\(build))"
        case let (version?, nil): return "v\(version)"
        default: return "(version unknown)"   // only reachable outside a bundle
        }
    }

    /// What the counter is actually doing, in one phrase, for the menu and the
    /// tooltip. `listening` alone is not enough to answer that: it only means
    /// `engine.start()` returned, so it stays true while the app holds a device
    /// that has stopped delivering *and* while it holds one that delivers
    /// nothing but zeros. The diagnostics' health is what separates the three,
    /// and every user-facing status renders this one property so they cannot
    /// disagree about it.
    private var statusText: String {
        guard listening else { return offReason ?? "not listening" }
        switch diagnostics.health {
        case .ok:       return "listening"
        case .stalled:  return "no audio arriving — microphone may be stuck"
        // Names the remedy, because it is the only one that works and it is not
        // one anybody guesses: the device looks perfectly healthy everywhere it
        // is reported, including in System Settings.
        case .noSignal: return "microphone is silent — unplug it and reconnect it"
        }
    }

    private func refreshTitle() {
        // A distinct icon per unhealthy state: neither is "listening", and
        // neither is "off" either — the app is holding a microphone that isn't
        // working, the state that used to be indistinguishable from working.
        // ⚠️ rather than 🔇 for no-signal because that one needs the owner to
        // get up and physically re-plug something; nothing else clears it.
        var icon = "🎙️"
        if listening {
            switch diagnostics.health {
            case .ok:       icon = "😄"
            case .stalled:  icon = "🔇"
            case .noSignal: icon = "⚠️"
            }
        }
        let me = store.todayCount(origin: "me")
        let tv = store.todayCount(origin: "tv")
        // Two counters: your laughs vs the TV's, today.
        statusItem.button?.title = "\(icon) \(me)  📺 \(tv)"
        // "open menu to resume" is wrong advice for no-signal — resuming cannot
        // fix a device that survives a full process exit, so don't offer it.
        let hint = diagnostics.health == .noSignal
            ? "(reconnect the microphone)" : "(open menu to resume)"
        statusItem.button?.toolTip = listening && diagnostics.health == .ok
            ? "Today — you: \(me) · TV: \(tv)"
            : "LaughCounter — \(statusText) \(hint)"
        // refreshTitle() is called after every `listening` transition, so it's the
        // one chokepoint that keeps the power assertion in sync with the state.
        updateSleepAssertion()
    }

    /// Hold the idle-system-sleep assertion iff the user opted in *and* we're
    /// actually listening; release it otherwise. Idempotent — safe to call on any
    /// state change. Main-thread only (every caller is already on main).
    private func updateSleepAssertion() {
        let shouldHold = keepAwake && listening
        if shouldHold, sleepAssertion == nil {
            sleepAssertion = ProcessInfo.processInfo.beginActivity(
                options: [.idleSystemSleepDisabled],
                reason: "LaughCounter is listening for laughs")
            AppLog.shared.log("keep-awake: holding idle-sleep assertion")
        } else if !shouldHold, let token = sleepAssertion {
            ProcessInfo.processInfo.endActivity(token)
            sleepAssertion = nil
            AppLog.shared.log("keep-awake: released idle-sleep assertion")
        }
    }

    private func buildMenu() {
        let menu = NSMenu()
        menu.addItem(withTitle: "LaughCounter \(Self.versionLabel)",
                     action: nil, keyEquivalent: "")

        let stateItem = NSMenuItem(title: "Status: \(statusText)",
                                   action: nil, keyEquivalent: "")
        stateItem.isEnabled = false
        switch diagnostics.health {
        case .ok:
            break
        case .stalled:
            stateItem.toolTip = "The microphone is open but no audio has arrived for a "
                + "while. Try “Restart listening”; if that doesn't help, the device may "
                + "need to be unplugged and reconnected. Details are in the activity log."
        case .noSignal:
            // Deliberately does not suggest "Restart listening" first: measured
            // on this failure, restarting the engine, quitting the app entirely
            // and restarting coreaudiod all left the device streaming silence.
            // Only re-plugging it worked, so that is what the tooltip says. (#88)
            stateItem.toolTip = "The microphone is delivering audio at the normal rate, "
                + "but every sample is silent — the device is connected and not actually "
                + "capturing. Unplug it and plug it back in. Restarting listening or "
                + "quitting LaughCounter will not clear this, and the device still looks "
                + "healthy in System Settings. Details are in the activity log."
        }
        menu.addItem(stateItem)

        let voiceState = voice.isAvailable ? "on — say “I just laughed”" : "unavailable"
        let voiceItem = NSMenuItem(title: "Voice feedback: \(voiceState)",
                                   action: nil, keyEquivalent: "")
        voiceItem.isEnabled = false
        menu.addItem(voiceItem)

        menu.addItem(.separator())
        menu.addItem(withTitle: "I just laughed (log a miss)",
                     action: #selector(logMiss), keyEquivalent: "l")
        menu.addItem(withTitle: listening ? "Restart listening" : "Start listening",
                     action: #selector(resumeListening), keyEquivalent: "r")
        // Only offered while the counter is meant to be on: once paused, "Start
        // listening" above is the way back, so there is never a Pause and a Resume
        // item competing to describe the same state.
        if listeningIntent {
            let pauseItem = NSMenuItem(title: "Pause listening",
                                       action: #selector(pauseListening), keyEquivalent: "p")
            pauseItem.toolTip = "Stop counting and release the microphone until you "
                + "start it again. Sleeping the Mac while paused keeps it paused; "
                + "quitting and relaunching starts it listening again."
            menu.addItem(pauseItem)
        }

        let keepAwakeItem = NSMenuItem(title: "Keep Mac awake while listening",
                                       action: #selector(toggleKeepAwake), keyEquivalent: "")
        keepAwakeItem.state = keepAwake ? .on : .off
        keepAwakeItem.toolTip = "Blocks idle sleep so laughs are still heard during a long "
            + "movie. Won't stop lid-close or manual Sleep, and uses more battery."
        menu.addItem(keepAwakeItem)
        menu.addItem(withTitle: "Open laugh log…",
                     action: #selector(openLog), keyEquivalent: "")
        menu.addItem(withTitle: "Open activity log…",
                     action: #selector(openActivityLog), keyEquivalent: "")
        menu.addItem(.separator())
        menu.addItem(withTitle: "Quit LaughCounter",
                     action: #selector(quit), keyEquivalent: "q")
        for item in menu.items where item.action != nil { item.target = self }
        statusItem.menu = menu
    }

    @objc private func logMiss() { markMissed(source: "button") }
    @objc private func resumeListening() {
        AppLog.shared.log("manual resume requested")
        startFailureStreak = 0   // an explicit ask earns a full retry ladder again
        requestListening()       // clears any pause via offReason = nil
    }
    /// Switch the counter off until it's switched back on by hand. Deliberately
    /// *not* persisted: relaunching starts listening again, which is what an
    /// always-on box should do after a power cut. Because it clears the intent, a
    /// sleep/standby taken while paused comes back paused.
    @objc private func pauseListening() {
        offReason = "paused"
        startFailureStreak = 0            // nothing to recover from any more
        stopListening(reason: "paused by user")
    }
    @objc private func toggleKeepAwake() {
        keepAwake.toggle()
        UserDefaults.standard.set(keepAwake, forKey: keepAwakeDefaultsKey)
        AppLog.shared.log("keep-awake \(keepAwake ? "enabled" : "disabled")")
        updateSleepAssertion()
        buildMenu()   // reflect the checkmark
    }
    @objc private func openLog() { store.revealInFinder() }
    @objc private func openActivityLog() {
        NSWorkspace.shared.activateFileViewerSelecting([AppLog.shared.fileURL])
    }
    @objc private func quit() {
        AppLog.shared.log("app quitting")
        NSApp.terminate(nil)
    }

    /// Clean up before the process exits. Reached for every exit path that goes
    /// through `NSApp.terminate` — the menu Quit item, ⌘Q, the logout/shutdown
    /// quit Apple Event, and the SIGTERM/SIGINT/SIGHUP sources in main.swift that
    /// route catchable signals here. Not reached for SIGKILL (Force Quit,
    /// `kill -9`) or a crash — those are uncatchable; nothing in-process can
    /// release the mic on them.
    ///
    /// Releasing the microphone here is the whole point: if the process dies with
    /// the input tap still installed and the engine running, its CoreAudio IOProc
    /// stays registered on the input device. Some USB webcam mics get wedged by
    /// that and go silent — no input registered in System Settings — until they're
    /// physically unplugged and reconnected. Tearing down the tap + engine (and the
    /// speech recogniser, which also holds the audio stream) deregisters the IOProc
    /// so the device is handed cleanly back to the system.
    func applicationWillTerminate(_ notification: Notification) {
        sleeping = true          // gate any late config-change reaction during teardown
        AppLog.shared.log("terminating — \(diagnostics.snapshotLine())")
        diagnostics.stop()
        // stopListening: flushes the in-progress laugh, invalidates pending
        // restarts (generation bump), stops speech, removes the tap, stops the
        // engine, and (via refreshTitle) drops the keep-awake assertion.
        stopListening(reason: "app terminating")
        AppLog.shared.log("app terminated — microphone released")
    }

    private func showMicDenied() {
        statusItem.button?.title = "😄 ⚠️"
        let alert = NSAlert()
        alert.messageText = "LaughCounter needs the microphone"
        alert.informativeText = "Grant access in System Settings → Privacy & Security → "
            + "Microphone, then relaunch LaughCounter."
        alert.addButton(withTitle: "OK")
        alert.runModal()
    }
}

