+    /// `outputFormat` set one layer up. (#79)
+    private static func usableInput(_ devices: [InputDevice]) -> InputDevice? {
+        devices.first {
+            $0.isDefault && $0.isAlive && $0.sampleRate > 0 && $0.channels > 0
         }
     }

